def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_def = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_def += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    mutual_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C' and history[i][1] == 'C':
            mutual_c_streak += 1
        else:
            break

    recent_len = min(10, n)
    recent_opp_def = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            recent_opp_def += 1

    forgiven = 0
    punished = 0
    last_type = 'U'
    last_idx = -1

    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C':
            if history[i + 1][1] == 'C':
                forgiven += 1
                last_type = 'F'
                last_idx = i
            else:
                punished += 1
                last_type = 'P'
                last_idx = i

    cooperative = (opp_def * 2 < n and recent_opp_def <= 4)
    exploit_active = (
        last_type == 'F'
        and forgiven > punished
        and cooperative
        and (n - last_idx) <= 5
    )

    if exploit_active and last_opp == 'C':
        return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            if opp_def * 2 >= n or recent_opp_def >= 6:
                return 'D'
            return 'C'

        stable = (
            mutual_c_streak >= 8
            and recent_opp_def == 0
            and opp_def <= max(2, n // 3)
        )
        if stable:
            if n <= 97 and forgiven + punished == 0:
                return 'D'
            if (
                n <= 95
                and forgiven > punished * 2
                and (last_type != 'P' or (n - last_idx) > 12)
            ):
                return 'D'
        return 'C'

    if opp_d_streak >= 3 or opp_def * 2 >= n or recent_opp_def >= 6:
        return 'D'

    if last_type == 'P' and (n - last_idx) <= 4 and opp_def <= max(3, n // 3):
        return 'C'

    if opp_d_streak == 1 and opp_def <= max(2, n // 4) and recent_opp_def <= 2:
        return 'C'

    if last_me == 'D' and opp_d_streak == 1 and opp_def <= max(3, n // 3):
        return 'C'

    return 'D'
